successful_actions.command:
cat > camp_zipnerf/internal/pycolmap_compat.py << 'EOF'
"""Compatibility layer for pycolmap SceneManager in newer versions."""

import pycolmap


class SceneManager:
  """Compatibility shim for old pycolmap.SceneManager.

  Provides the same interface as the deprecated SceneManager class
  using the newer pycolmap.Reconstruction API.
  """

  def __init__(self, path):
    """Initialize SceneManager from a COLMAP reconstruction path.

    Args:
      path: Path to a COLMAP reconstruction (sparse) directory.
    """
    self._reconstruction = pycolmap.Reconstruction(path)
    self.cameras = {}
    self.images = {}
    self.points3D = {}

  def load_cameras(self):
    """Load cameras from the reconstruction."""
    for cam_id, cam in self._reconstruction.cameras.items():
      self.cameras[cam_id] = cam

  def load_images(self):
    """Load images from the reconstruction."""
    for im_id, im in self._reconstruction.images.items():
      self.images[im_id] = im

  def load_points3D(self):
    """Load 3D points from the reconstruction."""
    for pt_id, pt in self._reconstruction.points3D.items():
      self.points3D[pt_id] = pt


# Monkey-patch pycolmap to add SceneManager
pycolmap.SceneManager = SceneManager
EOF

